    if 'bus' in data: print("Bus count:", len(data['bus']))
    if 'gen' in data: print("Gen count:", len(data['gen']))
    if 'branch' in data: print("Branch count:", len(data['branch']))
    if 'gencost' in data: print("Gencost count:", len(data['gencost']))
    if 'reserve_capacity' in data: print("Reserve Capacity count:", len(data['reserve_capacity']))
    if 'reserve_requirement' in data: print("Reserve Requirement:", data['reserve_requirement'])

except Exception as e:
    print(f"Error: {e}")

